'use strict';
const courseStories={
 visual:{name:'Spot & Match',skill:'Visual differentiation',line:'Find the twins. Notice the little differences.',color:'#e8efdc',count:25},
 events:{name:'First, Then',skill:'Everyday sequences',line:'Plant a seed, pack a picnic, and see what happens next.',color:'#e5eddd',count:20},
 stories:{name:'Picture Stories',skill:'Story understanding',line:'A little problem. A helpful idea. A happy ending.',color:'#f3e4d9',count:20},
 meaning:{name:'Pictures Have Meaning',skill:'Pictures & everyday objects',line:'Find familiar things and discover what they can do.',color:'#e2ecee',count:20},
 words:{name:'Words and Meanings',skill:'Vocabulary & relationships',line:'Explore the words hiding in everyday things.',color:'#eee8d8',count:20,together:true},
 sentences:{name:'Who Did What?',skill:'Understanding sentences',line:'Meet our little friends. Who is doing what?',color:'#e7e9f0',count:20,together:true},
 sounds:{name:'Sound Explorers',skill:'Syllables, rhyme & speech sounds',line:'Clap a word. Find a rhyme. Listen for a tiny sound.',color:'#f4ead6',count:20,together:true}
};
function friendlySharedNote(key){return `<span class="together-note"><span aria-hidden="true">♧</span> Play together <span class="together-explain">${key==='sounds'?'A grown-up says the words and sounds.':'A grown-up reads or signs the instructions.'}</span></span>`;}
adultSupportBanner=function(key){return `<div class="adult-support friendly-support">${friendlySharedNote(key)}</div>`;};
function friendlyCourseCard(key){const c=courseStories[key],done=key==='visual'?Object.values(saved).filter(x=>x.complete).length:courseCompleted(key);return `<button class="library-card story-course-card" data-course="${key}" style="--course-tint:${c.color}"><div class="library-card-art">${friendlyCover(key)}${c.together?'<span class="adult-badge">Play together</span>':''}</div><div class="story-course-copy"><span class="card-num">${c.count} LITTLE GAMES</span><h2>${c.name}</h2><p>${c.line}</p><span class="library-card-foot"><span>${done?`${done} explored`:'Come and explore'}</span><b aria-hidden="true">→</b></span></div></button>`;}
libraryHome=function(){activeLearningCourse=null;app.innerHTML=`<section class="welcome-garden"><div class="welcome-copy"><span class="eyebrow">A LITTLE TIME TOGETHER</span><h1>Let’s make a<br><em>little discovery.</em></h1><p>Play, notice, wonder.<br>Small adventures for growing minds.</p><a href="#course-library" class="primary library-link">Find something to play <span aria-hidden="true">↓</span></a></div><div class="welcome-illustration" aria-hidden="true">${friendlyCover('stories')}<span class="illustration-caption">A story is better together.</span></div><div class="welcome-footer"><span>No hurry. No scores to chase.</span><span>A little play goes a long way.</span></div></section><section id="course-library"><div class="section-head"><div><span class="eyebrow">WHAT SHALL WE PLAY?</span><h2>Choose a little adventure.</h2></div><span class="micro">7 courses · 145 games</span></div><div class="library-grid">${Object.keys(courseStories).map(friendlyCourseCard).join('')}</div><div class="gentle-invitation"><div class="invitation-mascot" aria-hidden="true">${friendlyMascot()}</div><div><b>There’s no perfect place to start.</b><p>Follow a little interest. Repeat a favorite. Stop whenever you like.</p></div><button class="back" id="libraryAbout">For grown-ups →</button></div></section>`;document.querySelectorAll('[data-course]').forEach(b=>b.onclick=()=>openLearningCourse(b.dataset.course));bindLibraryNav();document.querySelector('#courseNav').onclick=()=>document.querySelector('#course-library').scrollIntoView({behavior:'smooth'});document.querySelector('#brand').onclick=e=>{e.preventDefault();libraryHome()};document.querySelector('#guideNav').onclick=()=>showLearningGuide(null);document.querySelector('#libraryAbout').onclick=()=>showLearningGuide(null);window.scrollTo({top:0,behavior:'instant'});};
function courseAbout(key){const c=key==='visual'?null:newCourseInfo[key];return `<details class="course-about"><summary><span>For grown-ups</span><span class="about-subtitle">The skill, who it may help, and ways to play</span><span aria-hidden="true">＋</span></summary><div class="about-columns"><div><h3>What we’re practicing</h3><p>${c?c.goal:'Visual differentiation: looking closely at shape, color, size, position, and small details to compare pictures.'}</p><h3>Why this may help</h3><p>${c?c.problem:'Some children choose by just one detail or find similar pictures hard to tell apart. These games offer small, supported opportunities to look and compare.'}</p></div><div><h3>Who might enjoy the practice?</h3><p>${c?c.who:'Children with an observed matching or comparison difficulty, including some children with autism, developmental delay, intellectual disability, or communication needs. Choose by the individual child’s needs.'}</p><h3>A gentle way to begin</h3><p>${c?.adultRequired?(key==='sounds'?'An adult is needed to say the English words and sounds. Read the short instruction and use the optional tips when useful.':'An adult is needed to read, sign, or model the language. Read the instruction and play together; there are no confirmation buttons.'):'Show one example, let the child explore, and offer a little help. A few comfortable minutes is plenty.'}</p></div></div><p class="about-limits">${c?c.limit:'These games are practice, not a diagnosis or a treatment for dyslexia. Visual or motor access may need individual adaptation.'} Learning on screen does not automatically transfer to reading or everyday life.</p><button class="secondary" id="learningGuide">More guidance & research →</button></details>`;}
function friendlyGameCard(key,index){const visual=key==='visual',c=visual?null:newCourseInfo[key],d=visual?courses[index]:c.games[index];const picture=visual?art(lessonData(index,0).target):key==='events'?learnPicture({scene:index,stage:1}):key==='stories'?learnPicture({story:index,stage:1}):pictureIcon(d.object);const completed=visual?saved[index]?.complete:learningProgress[key]?.[index]?.complete;return `<button class="course-card ${completed?'completed':''}" ${visual?'data-game':'data-learning-game'}="${index}"><div class="thumb" style="--tint:${courseStories[key].color}">${picture}${completed?'<span class="played-mark" aria-label="Explored">✓</span>':''}</div><span class="card-num">${String(index+1).padStart(2,'0')}</span><h3>${visual?d[0]:d.title}</h3><span class="card-bottom">${completed?'Play again':'Let’s play'} <span aria-hidden="true">→</span></span></button>`;}
function friendlyCourseHome(key){const visual=key==='visual',c=courseStories[key],done=visual?Object.values(saved).filter(x=>x.complete).length:courseCompleted(key);const total=c.count;app.innerHTML=`<div class="play-top"><button class="back" id="toLibrary">← Our adventures</button>${c.together?friendlySharedNote(key):'<span class="micro">At your own pace</span>'}</div><section class="course-hero friendly-course-hero" style="--course-tint:${c.color}"><div><span class="eyebrow">${c.skill.toUpperCase()}</span><h1>${c.name}</h1><p>${c.line}</p><button class="primary" id="startLearning">${done?'Play a little more':'Let’s play'} <span aria-hidden="true">→</span></button><span class="micro course-smallprint">${total} games · No hurry</span></div><div class="course-hero-art" aria-hidden="true">${friendlyCover(key)}</div></section>${courseAbout(key)}<section id="journey"><div class="section-head"><div><span class="eyebrow">ONE LITTLE DISCOVERY AT A TIME</span><h2>Pick a game.</h2></div><div class="progress-label">${done} of ${total} explored<div class="progress-track"><i style="width:${done/total*100}%"></i></div></div></div><div class="grid friendly-game-grid">${Array.from({length:total},(_,i)=>friendlyGameCard(key,i)).join('')}</div><p class="note">Start anywhere. Come back to a favorite. Every little try counts.</p></section>`;document.querySelector('#toLibrary').onclick=libraryHome;document.querySelector('#learningGuide').onclick=()=>visual?guide():showLearningGuide(key);document.querySelector('#startLearning').onclick=()=>{const next=Math.max(0,Array.from({length:total},(_,i)=>i).findIndex(i=>visual?!saved[i]?.complete:!learningProgress[key]?.[i]?.complete));visual?intro(next):learningIntro(next)};document.querySelectorAll(visual?'[data-game]':'[data-learning-game]').forEach(b=>b.onclick=()=>visual?intro(+b.dataset.game):learningIntro(+b.dataset.learningGame));document.querySelector('#guideNav').onclick=()=>visual?guide():showLearningGuide(key);document.querySelector('#courseNav').onclick=()=>document.querySelector('#journey').scrollIntoView({behavior:'smooth'});document.querySelector('#brand').onclick=e=>{e.preventDefault();libraryHome()};bindLibraryNav();window.scrollTo({top:0,behavior:'instant'});}
openLearningCourse=function(key){activeLearningCourse=key;friendlyCourseHome(key);};
renderLearningCourse=function(){friendlyCourseHome(activeLearningCourse)};
home=function(){activeLearningCourse?friendlyCourseHome(activeLearningCourse):libraryHome()};
function friendlyCompletion(){const wrap=app.querySelector('.game-wrap');if(!wrap)return;wrap.classList.add('friendly-complete');const heading=wrap.querySelector('h1'),first=wrap.querySelector('p'),icon=wrap.querySelector('.success-icon');if(icon){icon.innerHTML=friendlyMascot();icon.className='completion-friend';}if(heading)heading.textContent='Lovely exploring!';if(first)first.textContent='A little discovery to take into your day.';const stat=wrap.querySelector('.completion-stat');if(stat){const details=document.createElement('details');details.className='quiet-notes';details.innerHTML='<summary>For grown-ups · practice notes</summary>';stat.before(details);details.append(stat);const note=wrap.querySelector('p.micro');if(note)details.append(note);}const eyebrow=wrap.querySelector('.eyebrow');if(eyebrow)eyebrow.textContent='A GOOD PLACE TO PAUSE';const buttons=wrap.querySelectorAll('.game-controls button');buttons.forEach(b=>{if(/again/i.test(b.textContent))b.textContent='Play this again';else if(/next/i.test(b.textContent))b.textContent='Another little game →';else if(/back/i.test(b.textContent))b.textContent='Choose another game →';});}
const detailedVisualFinish=finish;finish=function(){detailedVisualFinish();friendlyCompletion()};
const detailedLearningFinish=learningFinish;learningFinish=function(){detailedLearningFinish();friendlyCompletion()};
const detailedAdultFinish=adultFinish;adultFinish=function(){detailedAdultFinish();friendlyCompletion()};
function friendlyMessage(message){if(!message||/take your time|look closely, then try|find its match|give the prompt first|choose with your grown-up/i.test(message))return '';if(/✓|you found|you connected|you explored/i.test(message))return 'A little discovery. Well done!';if(/another look|look again|different ways|needs another|not match|try.*again|explore.*again|compare the color and shape|that picture is the same/i.test(message))return 'Let’s take another look together.';if(/clue|outlined|here is the connected/i.test(message))return 'Here’s a little helping hand.';return message;}
function polishPlay(){const wrap=app.querySelector('.game-wrap');if(!wrap)return;wrap.classList.add('friendly-play');wrap.querySelectorAll(':scope>.eyebrow').forEach(n=>n.classList.add('quiet-eyebrow'));wrap.querySelectorAll('.learning-note:not(details)').forEach(n=>{const details=document.createElement('details');details.className='quiet-notes';details.innerHTML='<summary>A little tip for grown-ups</summary>';n.before(details);details.append(n);});wrap.querySelectorAll('.game-controls button,.play-top button').forEach(b=>{const text=b.textContent;if(/show.*clue|show.*hint/i.test(text))b.innerHTML='<span aria-hidden="true">✧</span> A little help';if(/next round|^Next →/.test(text))b.textContent='Next one →';if(/finish game/i.test(text))b.textContent='All done →';if(/start this round again|^Clear/i.test(text))b.textContent='Start again';if(b.id==='adultCheck'||b.id==='learningCheck')b.textContent='Let’s see ✓';if(b.id==='check-work')b.textContent='Does it match? ✓';if(/see example/i.test(text))b.textContent='Show me how';});}
const technicalRenderLearningTask=renderLearningTask;renderLearningTask=function(message){technicalRenderLearningTask(friendlyMessage(message));polishPlay()};
const technicalRenderInteractive=renderInteractive;renderInteractive=function(message){technicalRenderInteractive(friendlyMessage(message));polishPlay()};
const technicalPlay=play;play=function(){technicalPlay();polishPlay();const feedback=app.querySelector('.feedback');if(feedback&&feedback.textContent==='Find its match.')feedback.textContent='';};
function friendlySoundInstruction(s){const d=adultCourseInfo.sounds.games[s.index],item=d.items[s.round%3];let mode=d.mode;if(mode==='review')mode=['phonemeblend','phonemes','final'][s.round%3];
 const text={syllables:`Let’s clap “${item[0]}” together. One pebble for each beat.`,phonemes:`Listen to “${item[0]}”. One pebble for each sound.`,syllableblend:`Listen: ${String(item[1]).replaceAll('·','…')}. Which picture?`,syllablechoice:'Which word has just one beat?',rhyme:`What rhymes with “${item[0]}”?`,rhymeodd:'Which word sounds different at the end?',rhymeyes:`“${item[0]}”… “${item[1]}”. Do they rhyme?`,initial:`Listen for ${item[1]}. Which word starts that way?`,final:`Listen for ${item[1]}. Which word ends that way?`,initialmatch:`What starts like “${item[0]}”?`,finalmatch:`What ends like “${item[0]}”?`,initialodd:'Which word starts with a different sound?',phonemeblend:'Listen to the little sounds. What word do they make?'};
 return text[mode]||'Let’s listen and explore.';
}
function adultFriendlyInstruction(s){return activeLearningCourse==='sounds'?friendlySoundInstruction(s):s.adult.replace(/^Show me /,'Can you find ').replace(/\. Show me\.$/,'. Which picture matches?').replace(/\. Show me\./,'. Which picture matches?').replace(/^(Can you find .*)\.$/,'$1?').replace(/in our example\?/,'here?');}
const technicalAdultRender=renderAdultTask;
renderAdultTask=function(message){
 // The adult's support is guidance, not an interaction lock.
 adultState.ready=true;technicalAdultRender(friendlyMessage(message));const wrap=app.querySelector('.game-wrap'),s=adultState;
 wrap.querySelectorAll('.adult-support,.adult-prompt').forEach(n=>n.remove());const eye=wrap.querySelector(':scope>.eyebrow');if(eye)eye.textContent='LET’S PLAY TOGETHER';const childText=wrap.querySelector(':scope>p');if(childText){childText.textContent=adultFriendlyInstruction(s);childText.classList.add('play-invitation');}
 const guidance=document.createElement('details');guidance.className='quiet-notes grownup-whisper';guidance.innerHTML=`<summary>A little tip for grown-ups</summary><p>${s.adult}</p><p>${s.teach}</p>`;wrap.querySelector('.game-stage').after(guidance);
 const tiny=document.createElement('span');tiny.className='together-play-pill';tiny.textContent='Play together';const top=app.querySelector('.play-top');top.querySelector('.micro').replaceWith(tiny);
 if(activeLearningCourse==='sounds'&&['phonemeblend','syllablechoice','rhymeodd','initialodd'].includes(adultCourseInfo.sounds.games[s.index].mode)){const whisper=document.createElement('p');whisper.className='sound-whisper';const item=adultCourseInfo.sounds.games[s.index].items[s.round%3];whisper.textContent=adultCourseInfo.sounds.games[s.index].mode==='phonemeblend'?`Grown-up: say the sounds in “${item[0]}” separately.`:`Say the picture names together before choosing.`;childText.after(whisper);}
 const add=wrap.querySelector('#adultAdd');if(add)add.textContent='＋ A pebble';wrap.querySelectorAll('.sound-counter').forEach(n=>n.classList.add('pebble'));const next=wrap.querySelector('#adultNext');if(next)next.textContent=s.round===2?'All done →':'Next one →';polishPlay();wrap.classList.add('adult-friendly-play');
};
const detailedAdultIntro=adultIntro;adultIntro=function(index){detailedAdultIntro(index);const wrap=app.querySelector('.game-wrap');wrap.querySelector('.adult-support')?.remove();const intro=wrap.querySelector('.adult-instructions');if(intro){const details=document.createElement('details');details.className='quiet-notes';details.innerHTML='<summary>A little tip before you play</summary>';intro.before(details);details.append(intro);}const button=wrap.querySelector('#adultBegin');button.textContent='Let’s play together →';const p=wrap.querySelector(':scope>p');if(p)p.textContent=adultCourseInfo[activeLearningCourse].games[index].skill.replace(/^Understand /,'Explore ').replace(/^Attend to /,'Notice ');};
// Make large technical descriptions optional while keeping course explanations available.
const detailedLearningIntro=learningIntro;learningIntro=function(index){detailedLearningIntro(index);polishPlay()};
let largerPictures=false;try{largerPictures=JSON.parse(localStorage.getItem('spotmatch-comfort')||'false')}catch{}document.body.classList.toggle('larger-pictures',largerPictures);
function addComfortControl(){const dialog=[...document.querySelectorAll('dialog[open]')].at(-1);if(!dialog||dialog.querySelector('#largerPictures'))return;const control=document.createElement('label');control.className='comfort-control';control.innerHTML=`<input type="checkbox" id="largerPictures" ${largerPictures?'checked':''}><span><b>A little more room</b><small>Show larger pictures with more space between choices.</small></span>`;dialog.querySelector('h2').after(control);control.querySelector('input').onchange=e=>{largerPictures=e.target.checked;document.body.classList.toggle('larger-pictures',largerPictures);try{localStorage.setItem('spotmatch-comfort',JSON.stringify(largerPictures))}catch{}};}
const fullLearningGuide=showLearningGuide;showLearningGuide=function(key){fullLearningGuide(key);addComfortControl()};const fullVisualGuide=guide;guide=function(){fullVisualGuide();addComfortControl()};

libraryHome();
